// The intent ledger (backend `ledger.py`, spec 028): every rule of the specs with how much evidence backs it.
// Server mode reads the live repository; the demo reads this repository's own ledger, generated by scripts/gen_samples.py.
import { useEffect, useState } from "react";
import { useData } from "../DataContext";

export const STATES = ["proposed", "decided", "built", "covered", "verified", "failing"] as const;
export type LedgerState = (typeof STATES)[number];
export const TODAY: LedgerState[] = ["built", "covered", "verified", "failing"];

export interface Citation {
  file: string;
  line: number;
  kind: "test" | "code";
  feature: string;
  id: string;
  node: string;
}
export interface Run {
  id: string;
  passed: boolean;
  at: string;
  commit: string;
  command: string;
  exit_code: number;
  tests: string[];
}
export interface Intent {
  ref: string;
  feature: string;
  id: string;
  kind: "FR" | "SC";
  text: string;
  loc: string;
  text_hash: string;
  state: LedgerState;
  label: string;
  tests: Citation[];
  code: Citation[];
  last_run: Run | null;
  stale_run: Run | null;
  issues: string[];
  values?: BoundValue[];
  reason?: string;
  run_age?: number | null;
}
export interface BoundValue {
  ref: string;
  file: string;
  status: "ok" | "drift" | "broken";
  found: string | null;
  line: number | null;
  expected: string[];
  reason: string;
  changed_by: { commit: string | null; author: string | null; date: string | null; subject: string } | null;
  decisions?: { id: string; title: string; number: string }[];
}
export interface LedgerFeature {
  key: string;
  title: string;
  status: string;
  implemented: boolean;
  implemented_by: string;
  approval: string;
  approval_current: boolean;
}
export interface Ledger {
  features: LedgerFeature[];
  intents: Intent[];
  counts: Record<LedgerState, number>;
  total: number;
  orphans: Citation[];
  verify_command: string | null;
  records: Record<string, { ok: boolean; count: number; broken_at: string | null; reason: string }>;
}
export interface TimelineEvent {
  type: "version" | "intent" | "approval" | "verification";
  at: string | null;
  by: string | null;
  kind?: string;
  commit?: string | null;
  subject?: string;
  uncommitted?: boolean;
  text?: string | null;
  before?: string | null;
  after?: string | null;
  action?: string;
  via?: string;
  reason?: string;
  decision?: string;
  passed?: boolean;
  current_text?: boolean;
  entry?: string;
}
export interface History {
  ref: string;
  text: string;
  state: LedgerState;
  git: boolean;
  note: string;
  timeline: TimelineEvent[];
}

export type LedgerLoad = { status: "loading" } | { status: "none" } | { status: "ready"; ledger: Ledger; live: boolean };

export function useLedger(): LedgerLoad {
  const { loader } = useData();
  const [state, setState] = useState<LedgerLoad>({ status: "loading" });
  useEffect(() => {
    if (!loader) return;
    if (loader.issue || loader.mode === "embedded") {
      setState({ status: "none" });
      return;
    }
    let live = true;
    const server = loader.mode === "server";
    fetch(server ? "/api/ledger" : "/samples/ledger.json", { headers: { Accept: "application/json" } })
      .then((r) => (r.ok && (r.headers.get("content-type") ?? "").includes("json") ? r.json() : null))
      .then((j: Ledger | null) => live && setState(j && Array.isArray(j.intents) ? { status: "ready", ledger: j, live: server } : { status: "none" }))
      .catch(() => live && setState({ status: "none" }));
    return () => {
      live = false;
    };
  }, [loader]);
  return state;
}

export async function fetchHistory(ref: string): Promise<History | null> {
  try {
    const r = await fetch(`/api/ledger/history?ref=${encodeURIComponent(ref)}`, { headers: { Accept: "application/json" } });
    return r.ok ? ((await r.json()) as History) : null;
  } catch {
    return null;
  }
}
